// Logic template
var calc_output = [];

var race = parseFloat(race);
var sex = parseFloat(sex);
var age = parseFloat(age);
var smoker = parseFloat(smoker);
var bmi = parseFloat(bmi);
var htn = parseFloat(htn);
var sbp = parseFloat(sbp);
var dm = parseFloat(dm);
var glu = parseFloat(glu);
var tc = parseFloat(tc);
var hdl = parseFloat(hdl);
var qrs = parseFloat(qrs);

if (UOMSYSTEM == false) { 
    var tc = parseFloat(tc) * 38.67; 
    var hdl = parseFloat(hdl) * 38.67;
    var glu = parseFloat(glu) * 18;
}

// Trasformation
var lnage = Math.log(age);
var lnage2 = (Math.log(age)) ** 2;
var lnbmi = Math.log(bmi);
var lnsbp = Math.log(sbp);
var lnglu = Math.log(glu);
var lntc = Math.log(tc);
var lnhdl = Math.log(hdl);
var lnqrs = Math.log(qrs);

// Coefficients by subgroup 
var group;
if (sex === 0 && race === 0) group = "WM";       // White Male
else if (sex === 1 && race === 0) group = "WF";  // White Female
else if (sex === 0 && race === 1) group = "BM";  // Black Male
else group = "BF"; 

var C = {
  WM: { // White Men
    lnage: 41.94101,
    lnage2: -0.88115,
    smoker: 0.73839,
    lnbmi: 37.21577,
    lnsbp_t: 1.030508,
    lnsbp_u: 0.91252,
    lnglu_t: 0.90072,
    lnglu_u: 0.77805,
    lntc: 0.49323,
    lnhdl: -0.43683,
    lnqrs: 0.63224,
    lnage_lnbmi: -8.83278,
    lnage_lnsbp_t: 0,
    lnage_lnsbp_u: 0,
    lnage_smoker: 0,
    meancv: 171.59,
    s0: 0.98752
  },
  WF: { // White Women
    lnage: 20.54973,
    lnage2: 0,
    smoker: 11.01752,
    lnbmi: 1.32948,
    lnsbp_t: 12.94937,
    lnsbp_u: 11.86273,
    lnglu_t: 1.04503,
    lnglu_u: 0.91807,
    lntc: 0,
    lnhdl: -0.07455,
    lnqrs: 1.06089,
    lnage_lnbmi: 0,
    lnage_lnsbp_t: -2.96923,
    lnage_lnsbp_u: -2.72538,
    lnage_smoker: -2.50777,
    meancv: 99.7321,
    s0: 0.99348
  },
  BM: { // Black Men
    lnage: 2.88334,
    lnage2: 0,
    smoker: 1.65337,
    lnbmi: 1.16289,
    lnsbp_t: 2.31106,
    lnsbp_u: 2.17229,
    lnglu_t: 0.64704,
    lnglu_u: 0.57891,
    lntc: 0,
    lnhdl: -0.80691,
    lnqrs: 0.72646,
    lnage_lnbmi: 0,
    lnage_lnsbp_t: 0,
    lnage_lnsbp_u: 0,
    lnage_smoker: -0.24665,
    meancv: 28.7369,
    s0: 0.98295
  },
  BF: { // Black Women
    lnage: 51.75667,
    lnage2: 0,
    smoker: 0.76532,
    lnbmi: 21.24763,
    lnsbp_t: 28.97791,
    lnsbp_u: 28.1853,
    lnglu_t: 0.96695,
    lnglu_u: 0.79561,
    lntc: 0.32646,
    lnhdl: 0,
    lnqrs: 1.27475,
    lnage_lnbmi: -5.00068,
    lnage_lnsbp_t: -6.59777,
    lnage_lnsbp_u: -6.42425,
    lnage_smoker: 0,
    meancv: 233.978,
    s0: 0.9926
  }
}[group];

// Build linear predictor (IndX)
var beta_sbp = (htn === 1 ? C.lnsbp_t : C.lnsbp_u);
var beta_glu = (dm  === 1 ? C.lnglu_t : C.lnglu_u);
var beta_age_sbp = (htn === 1 ? C.lnage_lnsbp_t : C.lnage_lnsbp_u);

var IndX =
    C.lnage * lnage +
    C.lnage2 * lnage2 +
    C.smoker * smoker +
    C.lnbmi * lnbmi +
    beta_sbp * lnsbp +
    beta_glu * lnglu +
    C.lntc * lntc +
    C.lnhdl * lnhdl +
    C.lnqrs * lnqrs +
    C.lnage_lnbmi * (lnage * lnbmi) +
    beta_age_sbp * (lnage * lnsbp) +
    C.lnage_smoker * (lnage * smoker);

// Risk formula: 1 - S0^(exp(IndX - MeanCV))
var exponent = Math.exp(IndX - C.meancv);
var risk = (1 - Math.pow(C.s0, exponent)) * 100;

// Output
calc_output.push({
    name: 'mini',
    value: risk.toFixed(1),
    value_text: '%',
    message: '10-year HF Risk'
});
calc_output.push({
    name: '10638_PCP-HF Risk Score_result',
    value: risk.toFixed(1),
    value_text: '%',
    message: '10-year HF Risk'
});
